/* Framebuffer character driver */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/types.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <debug.h>
#include <errno.h>
#include <poll.h>

#include <nuttx/irq.h>
#include <nuttx/kmalloc.h>
#include <nuttx/fs/fs.h>
#include <nuttx/fs/ioctl.h>
#include <nuttx/video/fb.h>
#include <nuttx/clock.h>
#include <nuttx/wdog.h>
#include <nuttx/circbuf.h>
#include <nuttx/spinlock.h>
#include <nuttx/trace.h>
#include <nuttx/semaphore.h>

/****************************************************************************
 * Pre-processor definitions
 ****************************************************************************/

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct fb_priv_s
{
  /* Supports a singly linked list */

  FAR struct fb_priv_s *flink;

  int overlay;                    /* Overlay number */

  /* Polling fds of waiting threads */

  FAR struct pollfd *fds[CONFIG_VIDEO_FB_NPOLLWAITERS];

#ifdef CONFIG_FB_SYNC
  sem_t wait;
#endif
};

struct fb_paninfo_s
{
  FAR struct circbuf_s buf;       /* Pan buffer queued list */

  struct wdog_s wdog;             /* VSync offset timer */

  FAR struct fb_chardev_s *dev;
};

/* This structure defines one framebuffer device.  Note that which is
 * everything in this structure is constant data set up and initialization
 * time.  Therefore, no there is requirement for serialized access to this
 * structure.
 */

struct fb_chardev_s
{
  FAR struct fb_vtable_s *vtable;   /* Framebuffer interface */
  uint8_t plane;                    /* Video plan number */
  clock_t vsyncoffset;              /* VSync offset ticks */
  FAR struct fb_priv_s *head;
  FAR struct fb_paninfo_s *paninfo; /* Pan info array */
  size_t paninfo_count;             /* Pan info count */
  spinlock_t lock;                  /* Lock for this framebuffer */
};

struct fb_panelinfo_s
{
  FAR void *fbmem;                /* Start of frame buffer memory */
  size_t fblen;                   /* Size of the framebuffer */
  uint8_t fbcount;                /* Count of frame buffer */
  uint8_t bpp;                    /* Bits per pixel */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static FAR struct circbuf_s *fb_get_panbuf(FAR struct fb_chardev_s *fb,
                                           int overlay);
static int     fb_add_paninfo(FAR struct fb_chardev_s *fb,
                              FAR const union fb_paninfo_u *info,
                              int overlay);
static int     fb_clear_paninfo(FAR struct fb_chardev_s *fb,
                                int overlay);
static int     fb_open(FAR struct file *filep);
static int     fb_close(FAR struct file *filep);
static ssize_t fb_read(FAR struct file *filep, FAR char *buffer,
                       size_t buflen);
static ssize_t fb_write(FAR struct file *filep, FAR const char *buffer,
                        size_t buflen);
static off_t   fb_seek(FAR struct file *filep, off_t offset, int whence);
static int     fb_ioctl(FAR struct file *filep, int cmd, unsigned long arg);
static int     fb_mmap(FAR struct file *filep,
                       FAR struct mm_map_entry_s *map);
static int     fb_poll(FAR struct file *filep, FAR struct pollfd *fds,
                       bool setup);
static int     fb_get_panelinfo(FAR struct fb_chardev_s *fb,
                                FAR struct fb_panelinfo_s *panelinfo,
                                int overlay);
static int     fb_get_planeinfo(FAR struct fb_chardev_s *fb,
                                FAR struct fb_planeinfo_s *pinfo,
                                uint8_t display);
#ifdef CONFIG_FB_SYNC
static int     fb_sem_wait(FAR struct fb_chardev_s *fb,
                           FAR struct fb_priv_s *priv,
                           int overlay);
static void    fb_sem_post(FAR struct fb_chardev_s *fb, int overlay);
#endif

#ifdef CONFIG_BUILD_KERNEL
static int     fb_munmap(FAR struct task_group_s *group,
                         FAR struct mm_map_entry_s *entry,
                         FAR void *start, size_t length);
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct file_operations g_fb_fops =
{
  fb_open,       /* open */
  fb_close,      /* close */
  fb_read,       /* read */
  fb_write,      /* write */
  fb_seek,       /* seek */
  fb_ioctl,      /* ioctl */
  fb_mmap,       /* mmap */
  NULL,          /* truncate */
  fb_poll        /* poll */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fb_get_panbuf
 ****************************************************************************/

static FAR struct circbuf_s *fb_get_panbuf(FAR struct fb_chardev_s *fb,
                                           int overlay)
{
  int id = overlay + 1;

  DEBUGASSERT(id >= 0 && id < fb->paninfo_count);

  return &(fb->paninfo[id].buf);
}

/****************************************************************************
 * Name: fb_add_paninfo
 ****************************************************************************/

static int fb_add_paninfo(FAR struct fb_chardev_s *fb,
                          FAR const union fb_paninfo_u *info,
                          int overlay)
{
  FAR struct circbuf_s *panbuf;
  irqstate_t flags;
  ssize_t ret;

  DEBUGASSERT(fb != NULL);

  panbuf = fb_get_panbuf(fb, overlay);
  if (panbuf == NULL)
    {
      return -EINVAL;
    }

  /* Disable the interrupt when writing to the queue to
   * prevent it from being modified by the interrupted
   * thread during the writing process.
   */

  flags = spin_lock_irqsave(&fb->lock);

  /* Write planeinfo information to the queue. */

  ret = circbuf_write(panbuf, info, sizeof(union fb_paninfo_u));

  spin_unlock_irqrestore(&fb->lock, flags);
  if (ret != sizeof(union fb_paninfo_u))
    {
      gwarn("WARNING: circbuf_write(panbuf) failed\n");
    }

  return ret <= 0 ? -ENOSPC : OK;
}

/****************************************************************************
 * Name: fb_clear_paninfo
 ****************************************************************************/

static int fb_clear_paninfo(FAR struct fb_chardev_s *fb,
                            int overlay)
{
  FAR struct circbuf_s *panbuf;
  irqstate_t flags;

  DEBUGASSERT(fb != NULL);

  panbuf = fb_get_panbuf(fb, overlay);
  if (panbuf == NULL)
    {
      return -EINVAL;
    }

  /* Disable the interrupt when writing to the queue to
   * prevent it from being modified by the interrupted
   * thread during the writing process.
   */

  flags = spin_lock_irqsave(&fb->lock);

  circbuf_reset(panbuf);

  /* Re-enable interrupts */

  spin_unlock_irqrestore(&fb->lock, flags);
  return OK;
}

/****************************************************************************
 * Name: fb_open
 ****************************************************************************/

static int fb_open(FAR struct file *filep)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  irqstate_t flags;
  int ret;

  inode = filep->f_inode;
  fb    = inode->i_private;

  DEBUGASSERT(fb->vtable != NULL);

  priv = kmm_zalloc(sizeof(*priv));
  if (priv == NULL)
    {
      return -ENOMEM;
    }

  priv->overlay = FB_NO_OVERLAY;
#ifdef CONFIG_FB_SYNC
  nxsem_init(&priv->wait, 0, 0);
#endif

  flags = spin_lock_irqsave(&fb->lock);

  if (fb->head == NULL)
    {
      if (fb->vtable->open != NULL &&
          (ret = fb->vtable->open(fb->vtable)) < 0)
        {
          goto err_fb;
        }
    }

  /* Attach the open structure to the device */

  priv->flink = fb->head;
  fb->head = priv;
  spin_unlock_irqrestore(&fb->lock, flags);
  filep->f_priv = priv;

  return 0;

err_fb:
  spin_unlock_irqrestore(&fb->lock, flags);
#ifdef CONFIG_FB_SYNC
  nxsem_destroy(&priv->wait);
#endif
  kmm_free(priv);
  return ret;
}

/****************************************************************************
 * Name: fb_close
 ****************************************************************************/

static int fb_close(FAR struct file *filep)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  FAR struct fb_priv_s *curr;
  FAR struct fb_priv_s *prev;
  irqstate_t flags;
  int ret;

  inode = filep->f_inode;
  fb    = inode->i_private;
  priv  = filep->f_priv;

  DEBUGASSERT(fb->vtable != NULL && priv != NULL);

  flags = spin_lock_irqsave(&fb->lock);

  DEBUGASSERT(fb->head);
  if (fb->head->flink == NULL)
    {
      if (fb->vtable->close != NULL)
        {
          ret = fb->vtable->close(fb->vtable);
          if (ret < 0)
            {
              spin_unlock_irqrestore(&fb->lock, flags);
              return ret;
            }
        }
    }

  /* Find the open structure in the list of
   * open structures for the device.
   */

  for (prev = NULL, curr = fb->head;
        curr && curr != priv;
        prev = curr, curr = curr->flink);

  DEBUGASSERT(curr);

  /* Remove the structure from the device */

  if (prev)
    {
      prev->flink = priv->flink;
    }
  else
    {
      fb->head = priv->flink;
    }

  spin_unlock_irqrestore(&fb->lock, flags);

#ifdef CONFIG_FB_SYNC
  nxsem_destroy(&priv->wait);
#endif
  kmm_free(priv);

  return OK;
}

/****************************************************************************
 * Name: fb_read
 ****************************************************************************/

static ssize_t fb_read(FAR struct file *filep, FAR char *buffer, size_t len)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  struct fb_panelinfo_s panelinfo;
  size_t start;
  size_t end;
  size_t size;
  int ret;

  ginfo("len: %u\n", (unsigned int)len);

  /* Get the framebuffer instance */

  inode = filep->f_inode;
  fb    = inode->i_private;
  priv  = filep->f_priv;

  DEBUGASSERT(fb->vtable != NULL && priv != NULL);

  /* Get panel info */

  ret = fb_get_panelinfo(fb, &panelinfo, priv->overlay);

  if (ret < 0)
    {
      return ret;
    }

  /* Get the start and size of the transfer */

  start = filep->f_pos;
  if (start >= panelinfo.fblen)
    {
      return 0;  /* Return end-of-file */
    }

  end = start + len;
  if (end >= panelinfo.fblen)
    {
      end = panelinfo.fblen;
    }

  size = end - start;

  /* And transfer the data from the frame buffer */

  memcpy(buffer, panelinfo.fbmem + start, size);
  filep->f_pos += size;
  return size;
}

/****************************************************************************
 * Name: fb_write
 ****************************************************************************/

static ssize_t fb_write(FAR struct file *filep, FAR const char *buffer,
                        size_t len)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  struct fb_panelinfo_s panelinfo;
  size_t start;
  size_t end;
  size_t size;
  int ret;

  ginfo("len: %u\n", (unsigned int)len);

  /* Get the framebuffer instance */

  inode = filep->f_inode;
  fb    = inode->i_private;
  priv  = filep->f_priv;

  DEBUGASSERT(fb->vtable != NULL && priv != NULL);

  /* Get panel info */

  ret = fb_get_panelinfo(fb, &panelinfo, priv->overlay);

  if (ret < 0)
    {
      return ret;
    }

  /* Get the start and size of the transfer */

  start = filep->f_pos;
  if (start >= panelinfo.fblen)
    {
      return -EFBIG;  /* Cannot extend the framebuffer */
    }

  end = start + len;
  if (end >= panelinfo.fblen)
    {
      end = panelinfo.fblen;
    }

  size = end - start;

  /* And transfer the data into the frame buffer */

  memcpy(panelinfo.fbmem + start, buffer, size);
  filep->f_pos += size;
  return size;
}

/****************************************************************************
 * Name: fb_seek
 *
 * Description:
 *   Seek the logical file pointer to the specified position.  The offset
 *   is in units of pixels, with offset zero being the beginning of the
 *   framebuffer.
 *
 ****************************************************************************/

static off_t fb_seek(FAR struct file *filep, off_t offset, int whence)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  struct fb_panelinfo_s panelinfo;
  off_t newpos;
  int ret;

  ginfo("offset: %u whence: %d\n", (unsigned int)offset, whence);

  /* Get the framebuffer instance */

  inode = filep->f_inode;
  fb    = inode->i_private;
  priv  = filep->f_priv;

  DEBUGASSERT(fb->vtable != NULL && priv != NULL);

  /* Determine the new, requested file position */

  switch (whence)
    {
    case SEEK_CUR:
      newpos = filep->f_pos + offset;
      break;

    case SEEK_SET:
      newpos = offset;
      break;

    case SEEK_END:

      /* Get panel info */

      ret = fb_get_panelinfo(fb, &panelinfo, priv->overlay);

      if (ret < 0)
        {
          return ret;
        }

      newpos = panelinfo.fblen + offset;
      break;

    default:

      /* Return EINVAL if the whence argument is invalid */

      return -EINVAL;
    }

  /* Opengroup.org:
   *
   *  "The lseek() function shall allow the file offset to be set beyond the
   *   end of the existing data in the file. If data is later written at this
   *   point, subsequent reads of data in the gap shall return bytes with the
   *   value 0 until data is actually written into the gap."
   *
   * We can conform to the first part, but not the second.  Return EINVAL if
   *  "...the resulting file offset would be negative for a regular file,
   *   block special file, or directory."
   */

  if (newpos >= 0)
    {
      filep->f_pos = newpos;
      ret = newpos;
    }
  else
    {
      ret = -EINVAL;
    }

  return ret;
}

/****************************************************************************
 * Name: fb_ioctl
 *
 * Description:
 *   The standard ioctl method.
 *
 ****************************************************************************/

static int fb_ioctl(FAR struct file *filep, int cmd, unsigned long arg)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  int ret = OK;

  ginfo("cmd: %d arg: %ld\n", cmd, arg);

  /* Get the framebuffer instance */

  inode = filep->f_inode;
  fb    = inode->i_private;

  /* Process the IOCTL command */

  switch (cmd)
    {
      case FBIOGET_VIDEOINFO:  /* Get color plane info */
        {
          FAR struct fb_videoinfo_s *vinfo =
            (FAR struct fb_videoinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(vinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->getvideoinfo == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->getvideoinfo(fb->vtable, vinfo);
        }
        break;

      case FBIOGET_PLANEINFO:  /* Get video plane info */
        {
          FAR struct fb_planeinfo_s *pinfo =
            (FAR struct fb_planeinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(pinfo != NULL);
          ret = fb_get_planeinfo(fb, pinfo, pinfo->display);
        }
        break;

#ifdef CONFIG_FB_CMAP
      case FBIOGET_CMAP:       /* Get RGB color mapping */
        {
          FAR struct fb_cmap_s *cmap =
            (FAR struct fb_cmap_s *)((uintptr_t)arg);

          DEBUGASSERT(cmap != NULL && fb->vtable != NULL);
          if (fb->vtable->getcmap == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->getcmap(fb->vtable, cmap);
        }
        break;

      case FBIOPUT_CMAP:       /* Put RGB color mapping */
        {
          FAR const struct fb_cmap_s *cmap =
            (FAR struct fb_cmap_s *)((uintptr_t)arg);

          DEBUGASSERT(cmap != NULL && fb->vtable != NULL);
          if (fb->vtable->putcmap == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->putcmap(fb->vtable, cmap);
        }
        break;
#endif
#ifdef CONFIG_FB_HWCURSOR
      case FBIOGET_CURSOR:     /* Get cursor attributes */
        {
          FAR struct fb_cursorattrib_s *attrib =
            (FAR struct fb_cursorattrib_s *)((uintptr_t)arg);

          DEBUGASSERT(attrib != NULL && fb->vtable != NULL);
          if (fb->vtable->getcursor == NULL)
            {
              ret = -ENOTTY;
            }

          ret = fb->vtable->getcursor(fb->vtable, attrib);
        }
        break;

      case FBIOPUT_CURSOR:     /* Set cursor attributes */
        {
          FAR struct fb_setcursor_s *cursor =
            (FAR struct fb_setcursor_s *)((uintptr_t)arg);

          DEBUGASSERT(cursor != NULL && fb->vtable != NULL);
          if (fb->vtable->setcursor == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setcursor(fb->vtable, cursor);
        }
        break;
#endif

#ifdef CONFIG_FB_UPDATE
      case FBIO_UPDATE:  /* Update the modified framebuffer data  */
        {
          struct fb_area_s *area = (FAR struct fb_area_s *)((uintptr_t)arg);

          DEBUGASSERT(fb->vtable != NULL);
          if (fb->vtable->updatearea == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->updatearea(fb->vtable, area);
        }
        break;
#endif

#ifdef CONFIG_FB_SYNC
      case FBIO_WAITFORVSYNC:  /* Wait upon vertical sync */
        {
          FAR struct fb_priv_s *priv = (FAR struct fb_priv_s *)filep->f_priv;

          DEBUGASSERT(fb->vtable != NULL);
          if (fb->vtable->waitforvsync != NULL)
            {
              ret = fb->vtable->waitforvsync(fb->vtable);
              break;
            }

          ret = fb_sem_wait(fb, priv, priv->overlay);
        }
        break;
#endif

#ifdef CONFIG_FB_OVERLAY
      case FBIO_SELECT_OVERLAY:  /* Select video overlay */
        {
          struct fb_overlayinfo_s oinfo;
          FAR struct fb_priv_s *priv = filep->f_priv;

          DEBUGASSERT(priv != NULL && fb->vtable != NULL);
          if (fb->vtable->getoverlayinfo == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          if (arg != FB_NO_OVERLAY)
            {
              memset(&oinfo, 0, sizeof(oinfo));
              ret = fb->vtable->getoverlayinfo(fb->vtable, arg, &oinfo);
            }

          if (ret >= 0)
            {
              priv->overlay = arg;
            }
        }
        break;

      case FBIOGET_OVERLAYINFO:  /* Get video overlay info */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->getoverlayinfo == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->getoverlayinfo(fb->vtable,
                                           oinfo->overlay, oinfo);
        }
        break;

      case FBIOSET_TRANSP:  /* Set video overlay transparency */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->settransp == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->settransp(fb->vtable, oinfo);
        }
        break;

      case FBIOSET_CHROMAKEY:  /* Set video overlay chroma key */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->setchromakey == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setchromakey(fb->vtable, oinfo);
        }
        break;

      case FBIOSET_COLOR:  /* Set video overlay color */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->setcolor == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setcolor(fb->vtable, oinfo);
        }
        break;

      case FBIOSET_BLANK:  /* Blank or unblank video overlay */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->setblank == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setblank(fb->vtable, oinfo);
        }
        break;

      case FBIOSET_AREA:  /* Set active video overlay area */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->setarea == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setarea(fb->vtable, oinfo);
        }
        break;

      case FBIOSET_DESTAREA:  /* Set destination area on the primary FB */
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->setdestarea == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setdestarea(fb->vtable, oinfo);
        }
        break;

#ifdef CONFIG_FB_OVERLAY_BLIT
      case FBIOSET_BLIT:  /* Blit operation between video overlays */
        {
          FAR struct fb_overlayblit_s *blit =
            (FAR struct fb_overlayblit_s *)((uintptr_t)arg);

          DEBUGASSERT(blit != NULL && fb->vtable != NULL);
          if (fb->vtable->blit == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->blit(fb->vtable, blit);
        }
        break;

      case FBIOSET_BLEND:  /* Blend operation between video overlays */
        {
          FAR struct fb_overlayblend_s *blend =
            (FAR struct fb_overlayblend_s *)((uintptr_t)arg);

          DEBUGASSERT(blend != NULL && fb->vtable != NULL);
          if (fb->vtable->blend == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->blend(fb->vtable, blend);
        }
        break;
#endif

      case FBIOPAN_OVERLAY:
        {
          FAR struct fb_overlayinfo_s *oinfo =
            (FAR struct fb_overlayinfo_s *)((uintptr_t)arg);
          union fb_paninfo_u paninfo;

          DEBUGASSERT(oinfo != NULL && fb->vtable != NULL);

          memcpy(&paninfo, oinfo, sizeof(*oinfo));

          if (fb->vtable->panoverlay != NULL)
            {
              fb->vtable->panoverlay(fb->vtable, oinfo);
            }

          ret = fb_add_paninfo(fb, &paninfo, oinfo->overlay);
        }
        break;

#endif /* CONFIG_FB_OVERLAY */

      case FBIOSET_POWER:
        {
          DEBUGASSERT(fb->vtable != NULL);
          if (fb->vtable->setpower == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->setpower(fb->vtable, (int)arg);
        }
        break;

      case FBIOGET_POWER:
        {
          FAR int *power = (FAR int *)((uintptr_t)arg);

          DEBUGASSERT(power != NULL && fb->vtable != NULL);
          if (fb->vtable->getpower == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          *power = fb->vtable->getpower(fb->vtable);
        }
        break;

      case FBIOGET_FRAMERATE:
        {
          FAR int *rate = (FAR int *)((uintptr_t)arg);

          DEBUGASSERT(rate != NULL && fb->vtable != NULL);
          if (fb->vtable->getframerate == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          *rate = fb->vtable->getframerate(fb->vtable);
        }
        break;

      case FBIOSET_FRAMERATE:
        {
          DEBUGASSERT(fb->vtable != NULL &&
                      fb->vtable->setframerate != NULL);
          ret = fb->vtable->setframerate(fb->vtable, (int)arg);
        }
        break;

      case FBIOPAN_DISPLAY:
        {
          FAR struct fb_planeinfo_s *pinfo =
            (FAR struct fb_planeinfo_s *)((uintptr_t)arg);
          union fb_paninfo_u paninfo;

          DEBUGASSERT(pinfo != NULL && fb->vtable != NULL);

          memcpy(&paninfo, pinfo, sizeof(*pinfo));

          if (fb->vtable->pandisplay != NULL)
            {
              fb->vtable->pandisplay(fb->vtable, pinfo);
            }

          ret = fb_add_paninfo(fb, &paninfo, FB_NO_OVERLAY);
        }
        break;

      case FBIOPAN_CLEAR:
        {
          ret = fb_clear_paninfo(fb, (int)arg);
        }
        break;

      case FBIOSET_VSYNCOFFSET:
        {
          fb->vsyncoffset = USEC2TICK(arg);
        }
        break;

      case FBIOGET_VSCREENINFO:
        {
          struct fb_videoinfo_s vinfo;
          struct fb_planeinfo_s pinfo;
          FAR struct fb_var_screeninfo *varinfo =
            (FAR struct fb_var_screeninfo *)((uintptr_t)arg);

          DEBUGASSERT(varinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->getvideoinfo == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->getvideoinfo(fb->vtable, &vinfo);
          if (ret < 0)
            {
              break;
            }

          ret = fb_get_planeinfo(fb, &pinfo, 0);
          if (ret < 0)
            {
              break;
            }

          memset(varinfo, 0, sizeof(struct fb_var_screeninfo));
          varinfo->xres           = vinfo.xres;
          varinfo->yres           = vinfo.yres;
          varinfo->xres_virtual   = pinfo.xres_virtual;
          varinfo->yres_virtual   = pinfo.yres_virtual;
          varinfo->xoffset        = pinfo.xoffset;
          varinfo->yoffset        = pinfo.yoffset;
          varinfo->bits_per_pixel = pinfo.bpp;
          varinfo->grayscale      = FB_ISMONO(vinfo.fmt);
          switch (vinfo.fmt)
            {
              case FB_FMT_Y1:
                varinfo->red.offset    = 0;
                varinfo->green.offset  = 0;
                varinfo->blue.offset   = 0;
                varinfo->red.length    = 1;
                varinfo->green.length  = 1;
                varinfo->blue.length   = 1;
                break;

              case FB_FMT_Y8:
                varinfo->red.offset    = 0;
                varinfo->green.offset  = 0;
                varinfo->blue.offset   = 0;
                varinfo->red.length    = 8;
                varinfo->green.length  = 8;
                varinfo->blue.length   = 8;
                break;

              case FB_FMT_RGB16_555:
                varinfo->red.offset    = 10;
                varinfo->green.offset  = 5;
                varinfo->blue.offset   = 0;
                varinfo->red.length    = 5;
                varinfo->green.length  = 5;
                varinfo->blue.length   = 5;
                break;

              case FB_FMT_RGB16_565:
                varinfo->red.offset    = 11;
                varinfo->green.offset  = 5;
                varinfo->blue.offset   = 0;
                varinfo->red.length    = 5;
                varinfo->green.length  = 6;
                varinfo->blue.length   = 5;
                break;

              case FB_FMT_RGB24:
              case FB_FMT_RGB32:
                varinfo->red.offset    = 16;
                varinfo->green.offset  = 8;
                varinfo->blue.offset   = 0;
                varinfo->red.length    = 8;
                varinfo->green.length  = 8;
                varinfo->blue.length   = 8;
                break;

              case FB_FMT_RGBA32:
                varinfo->red.offset    = 16;
                varinfo->green.offset  = 8;
                varinfo->blue.offset   = 0;
                varinfo->transp.offset = 24;
                varinfo->red.length    = 8;
                varinfo->green.length  = 8;
                varinfo->blue.length   = 8;
                varinfo->transp.length = 8;
                break;
          }
        }
        break;

      case FBIOGET_FSCREENINFO:
        {
          struct fb_videoinfo_s vinfo;
          struct fb_planeinfo_s pinfo;
          FAR struct fb_fix_screeninfo *fixinfo =
            (FAR struct fb_fix_screeninfo *)((uintptr_t)arg);

          DEBUGASSERT(fixinfo != NULL && fb->vtable != NULL);
          if (fb->vtable->getvideoinfo == NULL)
            {
              ret = -ENOTTY;
              break;
            }

          ret = fb->vtable->getvideoinfo(fb->vtable, &vinfo);
          if (ret < 0)
            {
              break;
            }

          ret = fb_get_planeinfo(fb, &pinfo, 0);
          if (ret < 0)
            {
              break;
            }

          memset(fixinfo, 0, sizeof(struct fb_fix_screeninfo));
#ifdef CONFIG_FB_MODULEINFO
          strlcpy(fixinfo->id, (FAR const char *)vinfo.moduleinfo,
                  sizeof(fixinfo->id));
#endif
          fixinfo->smem_start  = (unsigned long)pinfo.fbmem;
          fixinfo->smem_len    = pinfo.fblen;
          fixinfo->type        = FB_ISYUVPLANAR(vinfo.fmt) ?
                                 FB_TYPE_INTERLEAVED_PLANES :
                                 FB_TYPE_PACKED_PIXELS;
          fixinfo->visual      = FB_ISMONO(vinfo.fmt) ?
                                 FB_VISUAL_MONO10 : FB_VISUAL_TRUECOLOR;
          fixinfo->line_length = pinfo.stride;
        }
        break;

      case FBIOGET_PANINFOCNT:
        {
          ret = fb_paninfo_count(fb->vtable, (int)arg);
        }
        break;

      default:
        if (fb->vtable->ioctl != NULL)
          {
            ret = fb->vtable->ioctl(fb->vtable, cmd, arg);
          }
        else
          {
            gerr("ERROR: Unsupported IOCTL command: %d\n", cmd);
            ret = -ENOTTY;
          }
        break;
    }

  return ret;
}

#ifdef CONFIG_BUILD_KERNEL
static int fb_munmap(FAR struct task_group_s *group,
                     FAR struct mm_map_entry_s *entry,
                     FAR void *start, size_t length)
{
  if (group && entry)
    {
      ginfo("%p, len=%zu\n", entry->vaddr, entry->length);
      vm_unmap_region(get_group_mm(group), entry->vaddr, entry->length);
      mm_map_remove(get_current_mm(), entry);
    }

  return OK;
}
#endif

static int fb_mmap(FAR struct file *filep, FAR struct mm_map_entry_s *map)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  struct fb_panelinfo_s panelinfo;
  int ret;

  /* Get the framebuffer instance */

  inode = filep->f_inode;
  fb    = inode->i_private;
  priv  = filep->f_priv;

  DEBUGASSERT(fb->vtable != NULL && priv != NULL);

  /* Get panel info */

  ret = fb_get_panelinfo(fb, &panelinfo, priv->overlay);

  if (ret < 0)
    {
      return ret;
    }

  /* Return the address corresponding to the start of frame buffer. */

  if (map->offset >= 0 && map->offset < panelinfo.fblen &&
      map->length && map->offset + map->length <= panelinfo.fblen)
    {
#ifdef CONFIG_BUILD_KERNEL
      map->vaddr = vm_map_region(get_current_mm(),
                                 (uintptr_t)panelinfo.fbmem + map->offset,
                                 panelinfo.fblen);
      map->length = panelinfo.fblen;
      map->munmap = fb_munmap;
      mm_map_add(get_current_mm(), map);
#else
      map->vaddr = (FAR char *)panelinfo.fbmem + map->offset;
#endif
      return OK;
    }

  return -EINVAL;
}

/****************************************************************************
 * Name: fb_poll
 *
 * Description:
 *   Wait for framebuffer to be writable.
 *
 ****************************************************************************/

static int fb_poll(FAR struct file *filep, struct pollfd *fds, bool setup)
{
  FAR struct inode *inode;
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s *priv;
  FAR struct circbuf_s *panbuf;
  FAR struct pollfd **pollfds = NULL;
  irqstate_t flags;
  int ret = OK;
  int i;

  /* Get the framebuffer instance */

  inode = filep->f_inode;
  fb    = inode->i_private;
  priv  = filep->f_priv;

  DEBUGASSERT(fb->vtable != NULL && priv != NULL);

  flags = spin_lock_irqsave_nopreempt(&fb->lock);

  if (setup)
    {
      for (i = 0; i < CONFIG_VIDEO_FB_NPOLLWAITERS; ++i)
        {
          if (!priv->fds[i])
            {
              pollfds = &priv->fds[i];
              break;
            }
        }

      if (pollfds == NULL)
        {
          ret = -EBUSY;
          goto errout;
        }

      *pollfds = fds;
      fds->priv = pollfds;

      panbuf = fb_get_panbuf(fb, priv->overlay);
      if (!circbuf_is_full(panbuf))
        {
          poll_notify(&fds, 1, POLLOUT);
        }
    }
  else if (fds->priv != NULL)
    {
      /* This is a request to tear down the poll. */

      FAR struct pollfd **slot = (FAR struct pollfd **)fds->priv;
      *slot = NULL;
      fds->priv = NULL;
    }

errout:
  spin_unlock_irqrestore_nopreempt(&fb->lock, flags);
  return ret;
}

/****************************************************************************
 * Name: fb_get_panelinfo
 ****************************************************************************/

static int fb_get_panelinfo(FAR struct fb_chardev_s *fb,
                            FAR struct fb_panelinfo_s *panelinfo,
                            int overlay)
{
  struct fb_planeinfo_s pinfo;
  struct fb_videoinfo_s vinfo;
  int ret;

#ifdef CONFIG_FB_OVERLAY
  if (overlay != FB_NO_OVERLAY)
    {
      struct fb_overlayinfo_s oinfo;
      DEBUGASSERT(fb->vtable->getoverlayinfo != NULL);
      memset(&oinfo, 0, sizeof(oinfo));
      ret = fb->vtable->getoverlayinfo(fb->vtable, overlay, &oinfo);

      if (ret < 0)
        {
          gerr("ERROR: getoverlayinfo() failed: %d\n", ret);
          return ret;
        }

      panelinfo->fbmem   = oinfo.fbmem;
      panelinfo->fblen   = oinfo.fblen;
      panelinfo->fbcount = oinfo.yres_virtual == 0 ?
                           1 : (oinfo.yres_virtual / oinfo.yres);
      panelinfo->bpp     = oinfo.bpp;
      return OK;
    }
#endif

  ret = fb_get_planeinfo(fb, &pinfo, 0);
  if (ret < 0)
    {
      return ret;
    }

  ret = fb->vtable->getvideoinfo(fb->vtable, &vinfo);
  if (ret < 0)
    {
      gerr("ERROR: getvideoinfo() failed: %d\n", ret);
      return ret;
    }

  panelinfo->fbmem   = pinfo.fbmem;
  panelinfo->fblen   = pinfo.fblen;
  panelinfo->fbcount = pinfo.yres_virtual == 0 ?
                       1 : (pinfo.yres_virtual / vinfo.yres);
  panelinfo->bpp     = pinfo.bpp;

  return OK;
}

/****************************************************************************
 * Name: fb_get_planeinfo
 ****************************************************************************/

static int fb_get_planeinfo(FAR struct fb_chardev_s *fb,
                            FAR struct fb_planeinfo_s *pinfo,
                            uint8_t display)
{
  int ret;

  DEBUGASSERT(fb->vtable != NULL);
  DEBUGASSERT(fb->vtable->getplaneinfo != NULL);

  memset(pinfo, 0, sizeof(struct fb_planeinfo_s));
  pinfo->display = display;

  ret = fb->vtable->getplaneinfo(fb->vtable, fb->plane, pinfo);

  if (ret < 0)
    {
      gerr("ERROR: getplaneinfo() failed: %d\n", ret);
      return ret;
    }

  return OK;
}

/****************************************************************************
 * Name: fb_do_pollnotify
 ****************************************************************************/

static void fb_do_pollnotify(wdparm_t arg)
{
  FAR struct fb_paninfo_s *paninfo = (FAR struct fb_paninfo_s *)arg;
  FAR struct fb_chardev_s *fb = paninfo->dev;
  FAR struct fb_priv_s * priv;
  irqstate_t flags;
  int overlay;

  overlay = paninfo - paninfo->dev->paninfo - 1;

  flags = spin_lock_irqsave_nopreempt(&fb->lock);
  for (priv = paninfo->dev->head; priv; priv = priv->flink)
    {
      if (priv->overlay != overlay)
        {
          continue;
        }

      /* Notify framebuffer is writable. */

      poll_notify(priv->fds, CONFIG_VIDEO_FB_NPOLLWAITERS, POLLOUT);
    }

  spin_unlock_irqrestore_nopreempt(&fb->lock, flags);
}

#ifdef CONFIG_FB_SYNC
/****************************************************************************
 * Name: fb_sem_wait
 ****************************************************************************/

static int fb_sem_wait(FAR struct fb_chardev_s *fb,
                       FAR struct fb_priv_s *priv,
                       int overlay)
{
  struct fb_panelinfo_s panelinfo;
  int ret;

  ret = fb_get_panelinfo(fb, &panelinfo, overlay);
  if (ret < 0)
    {
      return ret;
    }

  if (fb_paninfo_count(fb->vtable, overlay) == panelinfo.fbcount)
    {
      ret = nxsem_wait(&priv->wait);
    }

  return ret;
}

/****************************************************************************
 * Name: fb_sem_post
 ****************************************************************************/

static void fb_sem_post(FAR struct fb_chardev_s *fb, int overlay)
{
  FAR struct fb_priv_s * priv;
  irqstate_t flags;

  DEBUGASSERT(fb != NULL);

  flags = spin_lock_irqsave_nopreempt(&fb->lock);

  for (priv = fb->head; priv; priv = priv->flink)
    {
      if (priv->overlay != overlay)
        {
          continue;
        }

      for (; ; )
        {
          int semcount = 0;

          sem_getvalue(&priv->wait, &semcount);
          if (semcount >= 0)
            {
              break;
            }

          /* Wakeup all waiters. */

          nxsem_post(&priv->wait);
        }
    }

  spin_unlock_irqrestore_nopreempt(&fb->lock, flags);
}
#endif

/****************************************************************************
 * Name: fb_pollnotify
 *
 * Description:
 *   Notify the waiting thread that the framebuffer can be written.
 *
 * Input Parameters:
 *   vtable - Pointer to framebuffer's virtual table.
 *
 ****************************************************************************/

static void fb_pollnotify(FAR struct fb_chardev_s *fb, int overlay)
{
  int id = overlay + 1;

  DEBUGASSERT(fb != NULL);

  DEBUGASSERT(id >= 0 && id < fb->paninfo_count);

  if (fb->vsyncoffset > 0)
    {
      wd_start(&fb->paninfo[id].wdog, fb->vsyncoffset, fb_do_pollnotify,
               (wdparm_t)(&fb->paninfo[id]));
    }
  else
    {
      fb_do_pollnotify((wdparm_t)(&fb->paninfo[id]));
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: fb_notify_vsync
 * Description:
 *   notify that the vsync comes.
 *
 * Input Parameters:
 *   vtable  - Pointer to framebuffer's virtual table.
 *
 ****************************************************************************/

void fb_notify_vsync(FAR struct fb_vtable_s *vtable)
{
  FAR struct fb_chardev_s *fb;
  FAR struct fb_priv_s * priv;
  irqstate_t flags;

  video_trace_mark(__func__);

  fb = vtable->priv;
  if (fb != NULL)
    {
      flags = spin_lock_irqsave_nopreempt(&fb->lock);
      for (priv = fb->head; priv; priv = priv->flink)
        {
          /* Notify that the vsync comes. */

          poll_notify(priv->fds, CONFIG_VIDEO_FB_NPOLLWAITERS, POLLPRI);
        }

      spin_unlock_irqrestore_nopreempt(&fb->lock, flags);
    }
}

/****************************************************************************
 * Name: fb_peek_paninfo
 * Description:
 *   Peek a frame from pan info queue of the specified overlay.
 *
 * Input Parameters:
 *   vtable  - Pointer to framebuffer's virtual table.
 *   info    - Pointer to pan info.
 *   overlay - Overlay index.
 *
 * Returned Value:
 *   Zero is returned on success; a negated errno value is returned on any
 *   failure.
 ****************************************************************************/

int fb_peek_paninfo(FAR struct fb_vtable_s *vtable,
                    FAR union fb_paninfo_u *info,
                    int overlay)
{
  FAR struct circbuf_s *panbuf;
  FAR struct fb_chardev_s *fb;
  irqstate_t flags;
  ssize_t ret;

  /* Prevent calling before getting the vtable. */

  fb = vtable->priv;
  if (fb == NULL)
    {
      return -EINVAL;
    }

  panbuf = fb_get_panbuf(fb, overlay);
  if (panbuf == NULL)
    {
      return -EINVAL;
    }

  flags = spin_lock_irqsave(&fb->lock);

  /* Attempt to peek a frame from the vsync queue. */

  ret = circbuf_peek(panbuf, info, sizeof(union fb_paninfo_u));
  DEBUGASSERT(ret <= 0 || ret == sizeof(union fb_paninfo_u));

  /* Re-enable interrupts */

  spin_unlock_irqrestore(&fb->lock, flags);
  return ret <= 0 ? -ENOSPC : OK;
}

/****************************************************************************
 * Name: fb_remove_paninfo
 * Description:
 *   Remove a frame from pan info queue of the specified overlay.
 *
 * Input Parameters:
 *   vtable  - Pointer to framebuffer's virtual table.
 *   overlay - Overlay index.
 *
 * Returned Value:
 *   Zero is returned on success; a negated errno value is returned on any
 *   failure.
 ****************************************************************************/

int fb_remove_paninfo(FAR struct fb_vtable_s *vtable, int overlay)
{
  FAR struct circbuf_s *panbuf;
  FAR struct fb_chardev_s *fb;
  irqstate_t flags;
  ssize_t ret;
  bool full;

  video_trace_mark(__func__);

  fb = vtable->priv;
  if (fb == NULL)
    {
      return -EINVAL;
    }

  panbuf = fb_get_panbuf(fb, overlay);
  if (panbuf == NULL)
    {
      return -EINVAL;
    }

  flags = spin_lock_irqsave(&fb->lock);

  full = (circbuf_space(panbuf) == 0);

  /* Attempt to take a frame from the pan info. */

  ret = circbuf_skip(panbuf, sizeof(union fb_paninfo_u));
  DEBUGASSERT(ret <= 0 || ret == sizeof(union fb_paninfo_u));

  /* Re-enable interrupts */

  spin_unlock_irqrestore(&fb->lock, flags);

  if (ret == sizeof(union fb_paninfo_u))
    {
      fb_pollnotify(fb, overlay);
      if (full)
        {
#ifdef CONFIG_FB_SYNC
          fb_sem_post(fb, overlay);
#endif
        }
    }

  return ret <= 0 ? -ENOSPC : OK;
}

/****************************************************************************
 * Name: fb_paninfo_count
 * Description:
 *   Get pan info count of specified overlay pan info queue.
 *
 * Input Parameters:
 *   vtable  - Pointer to framebuffer's virtual table.
 *   overlay - Overlay index.
 *
 * Returned Value:
 *   a non-negative value is returned on success; a negated errno value is
 *   returned on any failure.
 ****************************************************************************/

int fb_paninfo_count(FAR struct fb_vtable_s *vtable, int overlay)
{
  FAR struct circbuf_s *panbuf;
  FAR struct fb_chardev_s *fb;
  irqstate_t flags;
  ssize_t ret;

  /* Prevent calling before getting the vtable. */

  fb = vtable->priv;
  if (fb == NULL)
    {
      return -EINVAL;
    }

  panbuf = fb_get_panbuf(fb, overlay);
  if (panbuf == NULL)
    {
      return -EINVAL;
    }

  flags = spin_lock_irqsave(&fb->lock);

  ret = circbuf_used(panbuf) / sizeof(union fb_paninfo_u);

  spin_unlock_irqrestore(&fb->lock, flags);

  return ret;
}

/****************************************************************************
 * Name: fb_register_device
 *
 * Description:
 *   Register the framebuffer character device at /dev/fbN where N is the
 *   display number if the devices supports only a single plane.  If the
 *   hardware supports multiple color planes, then the device will be
 *   registered at /dev/fbN.M where N is the again display number but M
 *   is the display plane.
 *
 * Input Parameters:
 *   display - The display number for the case of boards supporting multiple
 *             displays or for hardware that supports multiple
 *             layers (each layer is consider a display).  Typically zero.
 *   plane   - Identifies the color plane on hardware that supports separate
 *             framebuffer "planes" for each color component.
 *   vtable  - Pointer to framebuffer's virtual table.
 *
 * Returned Value:
 *   Zero (OK) is returned success; a negated errno value is returned on any
 *   failure.
 *
 ****************************************************************************/

int fb_register_device(int display, int plane,
                       FAR struct fb_vtable_s *vtable)
{
  FAR struct fb_chardev_s *fb;
  struct fb_panelinfo_s panelinfo;
  struct fb_videoinfo_s vinfo;
  char devname[16];
  int nplanes;
  int ret;
  ssize_t i;

  /* Allocate a framebuffer state instance */

  fb = kmm_zalloc(sizeof(struct fb_chardev_s));
  if (fb == NULL)
    {
      return -ENOMEM;
    }

  DEBUGASSERT((unsigned)plane <= UINT8_MAX);
  DEBUGASSERT(vtable != NULL);
  fb->plane  = plane;
  fb->vtable = vtable;

  /* Initialize the frame buffer instance. */

  DEBUGASSERT(vtable->getvideoinfo != NULL);
  ret = vtable->getvideoinfo(vtable, &vinfo);
  if (ret < 0)
    {
      gerr("ERROR: getvideoinfo() failed: %d\n", ret);
      goto errout_with_fb;
    }

  nplanes = vinfo.nplanes;
  DEBUGASSERT(vinfo.nplanes > 0 && (unsigned)plane < vinfo.nplanes);

#ifdef CONFIG_FB_OVERLAY
  fb->paninfo_count = vinfo.noverlays;
#endif

  /* Add the primary framebuffer */

  fb->paninfo_count += 1;
  fb->paninfo = kmm_zalloc(sizeof(struct fb_paninfo_s) * fb->paninfo_count);

  if (fb->paninfo == NULL)
    {
      gerr("ERROR: alloc panbuf failed\n");
      goto errout_with_fb;
    }

  for (i = 0; i < fb->paninfo_count; i++)
    {
      ret = fb_get_panelinfo(fb, &panelinfo, i - 1);
      if (ret < 0)
        {
          goto errout_with_paninfo;
        }

      ret = circbuf_init(&(fb->paninfo[i].buf), NULL, panelinfo.fbcount
                         * sizeof(union fb_paninfo_u));

      DEBUGASSERT(ret == 0);

      fb->paninfo[i].dev = fb;

      /* Clear the framebuffer memory */

      memset(panelinfo.fbmem, 0, panelinfo.fblen);
    }

  /* Register the framebuffer device */

  if (nplanes < 2)
    {
      snprintf(devname, sizeof(devname), "/dev/fb%d", display);
    }
  else
    {
      snprintf(devname, sizeof(devname), "/dev/fb%d.%d", display, plane);
    }

  ret = register_driver(devname, &g_fb_fops, 0666, fb);

  if (ret < 0)
    {
      gerr("ERROR: register_driver() failed: %d\n", ret);
      goto errout_with_paninfo;
    }

  vtable->priv = fb;
  spin_lock_init(&fb->lock);
  return OK;

errout_with_paninfo:
  while (i-- > 0)
    {
      circbuf_uninit(&(fb->paninfo[i].buf));
    }

  kmm_free(fb->paninfo);
errout_with_fb:
  kmm_free(fb);
  return ret;
}

/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_fb.c
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/cache.h>
#include <nuttx/kmalloc.h>
#include <nuttx/video/fb.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include "artinchip_de.h"
#include "artinchip_lvds.h"
#include "artinchip_panel.h"

#define D13X_FB_WIDTH          1024u
#define D13X_FB_HEIGHT         600u
#define D13X_FB_BPP            16u
#define D13X_FB_STRIDE         (D13X_FB_WIDTH * 2u)
#define D13X_FB_FRAME_SIZE     (D13X_FB_STRIDE * D13X_FB_HEIGHT)
#define D13X_FB_BUFFERS        2u
#define D13X_FB_TOTAL_SIZE     (D13X_FB_FRAME_SIZE * D13X_FB_BUFFERS)
#define D13X_CACHE_LINE_SIZE   32u
#define D13X_CACHE_RANGE_LIMIT (64u * 1024u)
#define THEAD_MHCR_DCACHE_EN   (1u << 1)

struct d13x_fb_state_s
{
  bool initialized;
  bool power_on;
  uint8_t *memory;
};

static struct d13x_fb_state_s g_fb;

static void d13x_fb_clean_cache(void)
{
  uint32_t mhcr;

  /* The custom D13x port does not expose NuttX ARCH_DCACHE hooks, while the
   * E907 may inherit an enabled write-back cache from the bootloader.  Use
   * the vendor's numeric CSR and raw dcache.call encoding so ordinary GCC
   * toolchains still make framebuffer writes visible to the DE DMA master.
   */

  __asm__ __volatile__("csrr %0, 0x7c1" : "=r"(mhcr));
  if ((mhcr & THEAD_MHCR_DCACHE_EN) != 0)
    {
      __asm__ __volatile__("fence rw, rw" ::: "memory");
      __asm__ __volatile__(".long 0x0010000b" ::: "memory");
      __asm__ __volatile__("fence rw, rw" ::: "memory");
    }
}

static void d13x_fb_clean_cache_area(const void *address, size_t row_bytes,
                                     size_t stride, size_t row_count)
{
  uintptr_t row;
  uint32_t mhcr;
  size_t index;

  if (row_bytes == 0 || row_count == 0)
    {
      return;
    }

  /* A cache-wide clean is bounded by the cache capacity and is faster than
   * issuing tens of thousands of per-line operations for a large redraw.
   */

  if (row_bytes * row_count >= D13X_CACHE_RANGE_LIMIT)
    {
      d13x_fb_clean_cache();
      return;
    }

  __asm__ __volatile__("csrr %0, 0x7c1" : "=r"(mhcr));
  if ((mhcr & THEAD_MHCR_DCACHE_EN) == 0)
    {
      return;
    }

  __asm__ __volatile__("fence" ::: "memory");
  row = (uintptr_t)address;
  for (index = 0; index < row_count; index++)
    {
      uintptr_t current = row & ~(D13X_CACHE_LINE_SIZE - 1u);
      uintptr_t end = (row + row_bytes + D13X_CACHE_LINE_SIZE - 1u) &
                      ~(D13X_CACHE_LINE_SIZE - 1u);

      while (current < end)
        {
          register uintptr_t cache_address __asm__("a0") = current;

          /* T-Head dcache.cpa cleans one physical cache line. */

          __asm__ __volatile__(".long 0x0295000b" : "+r"(cache_address) ::
                               "memory");
          current += D13X_CACHE_LINE_SIZE;
        }

      row += stride;
    }

  __asm__ __volatile__("fence\n\t"
                       "fence.i\n\t"
                       ".long 0x01a0000b" ::: "memory");
}

static int d13x_fb_getvideoinfo(struct fb_vtable_s *vtable,
                                struct fb_videoinfo_s *vinfo)
{
  (void)vtable;

  if (vinfo == NULL)
    {
      return -EINVAL;
    }

  vinfo->fmt = FB_FMT_RGB16_565;
  vinfo->xres = D13X_FB_WIDTH;
  vinfo->yres = D13X_FB_HEIGHT;
  vinfo->nplanes = 1;
  return OK;
}

static int d13x_fb_getplaneinfo(struct fb_vtable_s *vtable, int planeno,
                                struct fb_planeinfo_s *pinfo)
{
  (void)vtable;

  if (planeno != 0 || pinfo == NULL || !g_fb.initialized)
    {
      return -EINVAL;
    }

  pinfo->fbmem = g_fb.memory;
  pinfo->fblen = D13X_FB_TOTAL_SIZE;
  pinfo->stride = D13X_FB_STRIDE;
  pinfo->display = 0;
  pinfo->bpp = D13X_FB_BPP;
  pinfo->xres_virtual = D13X_FB_WIDTH;
  pinfo->yres_virtual = D13X_FB_HEIGHT * D13X_FB_BUFFERS;
  pinfo->xoffset = 0;
  pinfo->yoffset = 0;
  return OK;
}

static int d13x_fb_pandisplay(struct fb_vtable_s *vtable,
                              struct fb_planeinfo_s *pinfo)
{
  uintptr_t address;

  (void)vtable;

  if (pinfo == NULL || !g_fb.initialized ||
      (pinfo->yoffset != 0 && pinfo->yoffset != D13X_FB_HEIGHT))
    {
      return -EINVAL;
    }

  address = (uintptr_t)g_fb.memory + pinfo->yoffset * D13X_FB_STRIDE;

  /* LVGL uses DIRECT double buffering.  Before drawing a new dirty area it
   * copies the previous frame's dirty areas into the back buffer so both
   * Both LVGL draw buffers are complete physical framebuffer pages.  Clean
   * the complete (finite) data cache immediately before publishing the page
   * so all writes, including LVGL's sync-area copies, are visible to DE DMA.
   */

  d13x_fb_clean_cache();
  d13x_de_set_framebuffer(address);
  return OK;
}

#ifdef CONFIG_FB_SYNC
static int d13x_fb_waitforvsync(struct fb_vtable_s *vtable)
{
  int ret;

  ret = d13x_de_wait_for_vsync();

  /* Release the queued page after its frame boundary. */
  fb_remove_paninfo(vtable, FB_NO_OVERLAY);

  return ret;
}
#endif

static int d13x_fb_getpower(struct fb_vtable_s *vtable)
{
  (void)vtable;
  return g_fb.power_on ? 1 : 0;
}

static int d13x_fb_setpower(struct fb_vtable_s *vtable, int power)
{
  (void)vtable;

  if (!g_fb.initialized)
    {
      return -ENODEV;
    }

  if (power > 0 && !g_fb.power_on)
    {
      d13x_lvds_enable();
      d13x_de_enable();
      d13x_panel_enable();
      g_fb.power_on = true;
    }
  else if (power <= 0 && g_fb.power_on)
    {
      d13x_panel_disable();
      d13x_de_disable();
      d13x_lvds_disable();
      g_fb.power_on = false;
    }

  return OK;
}

static struct fb_vtable_s g_fb_vtable =
{
  .getvideoinfo = d13x_fb_getvideoinfo,
  .getplaneinfo = d13x_fb_getplaneinfo,
  .pandisplay = d13x_fb_pandisplay,
#ifdef CONFIG_FB_SYNC
  .waitforvsync = d13x_fb_waitforvsync,
#endif
  .getpower = d13x_fb_getpower,
  .setpower = d13x_fb_setpower,
};

int up_fbinitialize(int display)
{
  uint32_t hactive;
  uint32_t vactive;
  uint32_t hfp;
  uint32_t hbp;
  uint32_t hsync;
  uint32_t vfp;
  uint32_t vbp;
  uint32_t vsync;
  uint32_t pixel_clock;
  int ret;

  if (display != 0)
    {
      return -ENODEV;
    }

  if (g_fb.initialized)
    {
      return OK;
    }

  g_fb.memory = kmm_memalign(64, D13X_FB_TOTAL_SIZE);
  if (g_fb.memory == NULL)
    {
      return -ENOMEM;
    }

  memset(g_fb.memory, 0, D13X_FB_TOTAL_SIZE);
  d13x_fb_clean_cache();

  d13x_panel_get_timing(&hactive, &vactive, &hfp, &hbp, &hsync,
                         &vfp, &vbp, &vsync, &pixel_clock);

  ret = d13x_panel_initialize();
  if (ret < 0)
    {
      goto errout;
    }

  ret = d13x_lvds_initialize(pixel_clock);
  if (ret < 0)
    {
      goto errout;
    }

  ret = d13x_de_initialize(hactive, vactive, hfp, hbp, hsync,
                           vfp, vbp, vsync, D13X_FB_STRIDE);
  if (ret < 0)
    {
      goto errout;
    }

  d13x_de_set_framebuffer((uintptr_t)g_fb.memory);
  d13x_lvds_enable();
  d13x_de_enable();
  up_mdelay(20);
  d13x_panel_enable();

  g_fb.power_on = true;
  g_fb.initialized = true;
  return OK;

errout:
  d13x_panel_disable();
  d13x_de_disable();
  d13x_lvds_disable();
#ifdef CONFIG_FB_SYNC
  d13x_de_uninitialize_vsync();
#endif
  kmm_free(g_fb.memory);
  memset(&g_fb, 0, sizeof(g_fb));
  return ret;
}

struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  if (display != 0 || vplane != 0 || !g_fb.initialized)
    {
      return NULL;
    }

  return &g_fb_vtable;
}

void up_fbuninitialize(int display)
{
  if (display != 0 || !g_fb.initialized)
    {
      return;
    }

  d13x_panel_disable();
  d13x_de_disable();
  d13x_lvds_disable();
#ifdef CONFIG_FB_SYNC
  d13x_de_uninitialize_vsync();
#endif
  kmm_free(g_fb.memory);
  memset(&g_fb, 0, sizeof(g_fb));
}

/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_de.c
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/semaphore.h>
#include <nuttx/spinlock.h>

#include <errno.h>

#include "chip.h"
#include "artinchip_de.h"
#include "include/irq.h"

#define BIT(n)                    (1u << (n))

#define DE_CONFIG_UPDATE          0x008u
#define VIDEO_LAYER_CTRL          0x020u
#define UI_LAYER_CTRL             0x0a0u
#define UI_LAYER_SIZE             0x0a4u
#define UI_LAYER_RECT_CTRL        0x0b0u
#define UI_RECT_INPUT_SIZE        0x0c0u
#define UI_RECT_OFFSET            0x0c4u
#define UI_RECT_STRIDE            0x0c8u
#define UI_RECT_ADDR              0x0ccu
#define BLENDING_BG_COLOR         0x100u
#define BLENDING_OUTPUT_SIZE      0x104u
#define UI_LAYER_OFFSET           0x10cu
#define WB_CTRL                   0x170u
#define TIMING_CTRL               0x1d0u
#define TIMING_INIT               0x1d4u
#define TIMING_STATUS             0x1d8u
#define TIMING_LINE_SET           0x1dcu
#define TIMING_ACTIVE_SIZE        0x1e0u
#define TIMING_H_PORCH            0x1e4u
#define TIMING_V_PORCH            0x1e8u
#define TIMING_SYNC_PULSE         0x1ecu
#define TIMING_POLARITY           0x1f0u
#define QOS_UI                    0x88cu
#define QOS_URGENT                0x890u

#define UI_FORMAT_RGB565          0x0eu
#define UI_LAYER_ENABLE           BIT(0)
#define UI_ALPHA_ENABLE           BIT(2)
#define TIMING_ENABLE             BIT(0)
#define DE_SOFT_RESET_ENABLE      BIT(16)

#define CMU_CLK_DE                (D13X_CMU_BASE + 0x08c0u)
#define MOD_RESET_DEASSERT        BIT(13)
#define MOD_BUS_ENABLE            BIT(12)
#define MOD_CLOCK_ENABLE          BIT(8)
#define TIMING_V_BLANK_IRQ        BIT(0)

#ifdef CONFIG_FB_SYNC
static sem_t g_de_vsync_sem;
static bool g_de_vsync_initialized;
static volatile bool g_de_vsync_waiting;
static volatile uint32_t g_de_vsync_sequence;

static int d13x_de_interrupt(int irq, void *context, void *arg)
{
  uint32_t status;

  (void)irq;
  (void)context;
  (void)arg;

  status = getreg32(D13X_DE_BASE + TIMING_STATUS);
  putreg32(status, D13X_DE_BASE + TIMING_STATUS);
  if ((status & TIMING_V_BLANK_IRQ) != 0)
    {
      g_de_vsync_sequence++;
      if (g_de_vsync_waiting)
        {
          nxsem_post(&g_de_vsync_sem);
        }
    }

  return OK;
}
#endif

static inline void de_write(uint32_t offset, uint32_t value)
{
  putreg32(value, D13X_DE_BASE + offset);
}

static inline uint32_t de_size(uint32_t width, uint32_t height)
{
  return ((height & 0x1fffu) << 16) | (width & 0x1fffu);
}

int d13x_de_initialize(uint32_t width, uint32_t height,
                       uint32_t hfp, uint32_t hbp, uint32_t hsync,
                       uint32_t vfp, uint32_t vbp, uint32_t vsync,
                       uint32_t stride)
{
  uint32_t reg;

  if (width == 0 || height == 0 || width > 0x1fff || height > 0x1fff ||
      stride > 0x7fff)
    {
      return -EINVAL;
    }

  /* D13x DE v1.1 runs at 150 MHz from PLL_INT1 / 8. */

  reg = getreg32(CMU_CLK_DE);
  reg &= ~0x3fu;
  reg |= 7u | MOD_RESET_DEASSERT | MOD_BUS_ENABLE | MOD_CLOCK_ENABLE;
  putreg32(reg, CMU_CLK_DE);

  de_write(TIMING_CTRL, 0);
  de_write(VIDEO_LAYER_CTRL, 0);
  de_write(UI_LAYER_CTRL, 0);
  de_write(UI_LAYER_RECT_CTRL, 0);
  de_write(TIMING_INIT, 0);
  de_write(TIMING_STATUS, 0xffffffffu);

#ifdef CONFIG_FB_SYNC
  if (!g_de_vsync_initialized)
    {
      nxsem_init(&g_de_vsync_sem, 0, 0);
      if (irq_attach(D13X_IRQ_DE, d13x_de_interrupt, NULL) < 0)
        {
          nxsem_destroy(&g_de_vsync_sem);
          return -EIO;
        }

      g_de_vsync_initialized = true;
    }
#endif

  de_write(TIMING_ACTIVE_SIZE, de_size(width, height));
  de_write(TIMING_H_PORCH, ((hbp & 0x1fffu) << 16) |
                            (hfp & 0x1fffu));
  de_write(TIMING_V_PORCH, ((vbp & 0x1fffu) << 16) |
                            (vfp & 0x1fffu));
  de_write(TIMING_SYNC_PULSE, ((vsync & 0x7ffu) << 16) |
                               (hsync & 0x7ffu));
  de_write(TIMING_POLARITY, 0);
  de_write(TIMING_LINE_SET, 2u << 16);
#ifdef CONFIG_FB_SYNC
  de_write(TIMING_INIT, TIMING_V_BLANK_IRQ);
#else
  de_write(TIMING_INIT, 0);
#endif

  de_write(BLENDING_BG_COLOR, 0);
  de_write(BLENDING_OUTPUT_SIZE, de_size(width, height));
  de_write(UI_LAYER_SIZE, de_size(width, height));
  de_write(UI_LAYER_OFFSET, 0);
  de_write(UI_RECT_INPUT_SIZE, de_size(width, height));
  de_write(UI_RECT_OFFSET, 0);
  de_write(UI_RECT_STRIDE, stride);

  reg = (0xffu << 24) | (UI_FORMAT_RGB565 << 8) |
        UI_ALPHA_ENABLE | UI_LAYER_ENABLE;
  de_write(UI_LAYER_CTRL, reg);
  de_write(UI_LAYER_RECT_CTRL, BIT(0));

  reg = getreg32(D13X_DE_BASE + WB_CTRL);
  de_write(WB_CTRL, reg | DE_SOFT_RESET_ENABLE);

  de_write(QOS_UI, (0xdu << 28) | (0x60u << 16) |
                   (0xdu << 12) | 0x40u);
  de_write(QOS_URGENT, BIT(15) | BIT(14) | 0x40u);
  de_write(DE_CONFIG_UPDATE, BIT(0));
#ifdef CONFIG_FB_SYNC
  up_enable_irq(D13X_IRQ_DE);
#endif
  return OK;
}

void d13x_de_set_framebuffer(uintptr_t address)
{
  de_write(UI_RECT_ADDR, (uint32_t)address);
  de_write(DE_CONFIG_UPDATE, BIT(0));
}

void d13x_de_enable(void)
{
  uint32_t reg = getreg32(D13X_DE_BASE + TIMING_CTRL);
  de_write(TIMING_CTRL, reg | TIMING_ENABLE);
  de_write(DE_CONFIG_UPDATE, BIT(0));
}

void d13x_de_disable(void)
{
  uint32_t reg = getreg32(D13X_DE_BASE + TIMING_CTRL);
  de_write(TIMING_CTRL, reg & ~TIMING_ENABLE);
  de_write(DE_CONFIG_UPDATE, BIT(0));
}

#ifdef CONFIG_FB_SYNC
int d13x_de_wait_for_vsync(void)
{
  irqstate_t flags;
  uint32_t target;
  int ret;

  if (!g_de_vsync_initialized)
    {
      return -ENODEV;
    }

  flags = enter_critical_section();
  target = g_de_vsync_sequence + 1;
  while (nxsem_trywait(&g_de_vsync_sem) == OK)
    {
    }

  g_de_vsync_waiting = true;
  leave_critical_section(flags);

  do
    {
      if (g_de_vsync_sequence >= target)
        {
          ret = OK;
          break;
        }

      ret = nxsem_tickwait_uninterruptible(&g_de_vsync_sem,
                                           MSEC2TICK(100));
    }
  while (ret == OK);

  flags = enter_critical_section();
  g_de_vsync_waiting = false;
  while (nxsem_trywait(&g_de_vsync_sem) == OK)
    {
    }
  leave_critical_section(flags);

  return ret;
}

void d13x_de_uninitialize_vsync(void)
{
  if (g_de_vsync_initialized)
    {
      up_disable_irq(D13X_IRQ_DE);
      irq_detach(D13X_IRQ_DE);
      nxsem_destroy(&g_de_vsync_sem);
      g_de_vsync_initialized = false;
      g_de_vsync_waiting = false;
    }
}
#endif

